        public static int ResolveTranslucencyVolumeGridDepth(float nearPlane, float farPlane)
        {
            var distance = Mathf.Max(farPlane - nearPlane, 1f);
            return Mathf.Clamp((int)(Mathf.Log(distance * 0.02f + 1f, 2f) * 8f) + 1, 1, 64);
        }

